struct Pose2 {
    vect2d t;
    double th;
};

/// One relative SE2 measurement from an EDGE_SE2 record: pose `b` seen
/// from pose `a`'s body frame.
struct DeltaPose2 {
    uint32_t a, b;
    /// Measured translation in `a`'s frame.
    vect2d dt;
    /// Measured heading change.
    double dth;
    /// Information matrix upper triangle in file order:
    /// I11 I12 I13 I22 I23 I33, rows ordered (x y theta).
    double info[6];

    /// Sqrt-information row weights (wt, wr) when the information
    /// matrix is diagonal with equal translation entries; false when
    /// it is anything else.
    bool iso_sqrt_info(double& wt, double& wr) const {
        if (std::abs(info[1]) < 1e-9 && std::abs(info[2]) < 1e-9
            && std::abs(info[4]) < 1e-9 && std::abs(info[0] - info[3]) < 1e-9) {
            wt = std::sqrt(info[0]);
            wr = std::sqrt(info[5]);
            return true;
        }
        return false;
    }

    /// Eigen factors (r, w) of the information matrix for exact
    /// whitening of any symmetric information matrix:
    /// info = r * diag(w)^2 * r^T, so the weighted residual is
    /// diag(w) * r^T * res. Eigenvalues below zero (numerically
    /// indefinite input) clamp to zero weight, so near-singular
    /// matrices lose the degenerate direction instead of failing a
    /// factorization.
    std::pair<matrix3d, vect3d> eigen_sqrt_info() const {
        matrix3d m;
        m.rows[0] = {info[0], info[1], info[2]};
        m.rows[1] = {info[1], info[3], info[4]};
        m.rows[2] = {info[2], info[4], info[5]};
        auto rd = m.symmetric_eigen();
        vect3d w{rd.second.x > 0.0 ? std::sqrt(rd.second.x) : 0.0,
                 rd.second.y > 0.0 ? std::sqrt(rd.second.y) : 0.0,
                 rd.second.z > 0.0 ? std::sqrt(rd.second.z) : 0.0};
        return {rd.first, w};
    }
};

/// A 2D pose graph: poses and the relative measurements between them.
struct Dataset2 {
    std::vector<Pose2> poses;
    std::vector<DeltaPose2> deltas;

    /// Parse a 2D pose graph from .g2o text. Aborts on malformed
    /// records (with the 1-based line number).
    static Dataset2 parse(const std::string& text) {
        Dataset2 ds;
        size_t pos = 0, line_no = 0;
        while (pos < text.size()) {
            size_t eol = text.find('\n', pos);
            if (eol == std::string::npos) eol = text.size();
            std::string line = text.substr(pos, eol - pos);
            pos = eol + 1;
            line_no++;

            char tag[32];
            if (std::sscanf(line.c_str(), "%31s", tag) != 1) continue;
            if (std::string(tag) == "VERTEX_SE2") {
                unsigned long id;
                double x, y, th;
                arael_assert_true(std::sscanf(line.c_str(),
                    "%*s %lu %lf %lf %lf", &id, &x, &y, &th) == 4);
                arael_assert_true(id == ds.poses.size()); // dense, ordered
                ds.poses.push_back({{x, y}, th});
            } else if (std::string(tag) == "EDGE_SE2") {
                DeltaPose2 d;
                unsigned long a, b;
                arael_assert_true(std::sscanf(line.c_str(),
                    "%*s %lu %lu %lf %lf %lf %lf %lf %lf %lf %lf %lf",
                    &a, &b, &d.dt.x, &d.dt.y, &d.dth,
                    &d.info[0], &d.info[1], &d.info[2],
                    &d.info[3], &d.info[4], &d.info[5]) == 11);
                d.a = uint32_t(a);
                d.b = uint32_t(b);
                ds.deltas.push_back(d);
            }
        }
        for (const auto& d : ds.deltas)
            arael_assert_true(d.a < ds.poses.size() && d.b < ds.poses.size());
        return ds;
    }

    /// Read a 2D pose graph from a .g2o file. Aborts when the file
    /// cannot be read or parsed.
    static Dataset2 load(const char* path) {
        std::FILE* f = std::fopen(path, "rb");
        arael_assert_true(f != nullptr);
        std::string text;
        char buf[65536];
        size_t n;
        while ((n = std::fread(buf, 1, sizeof buf, f)) > 0)
            text.append(buf, n);
        std::fclose(f);
        return parse(text);
    }

    /// Render the pose graph as .g2o text -- byte-identical to the
    /// Rust writer.
    std::string to_g2o() const {
        std::string out;
        for (size_t i = 0; i < poses.size(); i++) {
            out += "VERTEX_SE2 ";
            out += std::to_string(i);
            out += ' '; g2o_num(out, poses[i].t.x);
            out += ' '; g2o_num(out, poses[i].t.y);
            out += ' '; g2o_num(out, poses[i].th);
            out += '\n';
        }
        for (const auto& d : deltas) {
            out += "EDGE_SE2 ";
            out += std::to_string(d.a);
            out += ' ';
            out += std::to_string(d.b);
            out += ' '; g2o_num(out, d.dt.x);
            out += ' '; g2o_num(out, d.dt.y);
            out += ' '; g2o_num(out, d.dth);
            for (double v : d.info) {
                out += ' ';
                g2o_num(out, v);
            }
            out += '\n';
        }
        return out;
    }

    /// Write the pose graph back out as .g2o. Aborts when the file
    /// cannot be written.
    void save(const char* path) const {
        std::string text = to_g2o();
        std::FILE* f = std::fopen(path, "wb");
        arael_assert_true(f != nullptr);
        arael_assert_true(
            std::fwrite(text.data(), 1, text.size(), f) == text.size());
        std::fclose(f);
    }
};

/// The file's qx qy qz qw, normalized (a zero-length quaternion
/// aborts).
inline quaternd unit_quat(double qw, vect3d v) {
    double n = std::sqrt(qw * qw + v.square());
    arael_assert_true(n >= 1e-12);
    return {qw / n, v * (1.0 / n)};
}

